import{H as e,at as t,it as n,vt as r}from"./chunks/framework.dmHZ7NHG.js";var i=JSON.parse(`{"title":"The sanitise standards","description":"","frontmatter":{},"headers":[],"params":{"slug":"sanitize","address":"dad0c39e-0a95-802a-9de2-3bafb59cf404","receipt":"8ef3fc8e-06aa-8e56-8cec-411d4f1a6b98"},"relativePath":"docs/publications/sanitize.md","filePath":"docs/publications/[slug].md"}`),a={name:`docs/publications/sanitize.md`};function o(e,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[t(`<h1 id="the-sanitise-standards" tabindex="-1">The sanitise standards <a class="header-anchor" href="#the-sanitise-standards" aria-label="Permalink to “The sanitise standards”">​</a></h1><blockquote><p>the engine&#39;s one input→output guard with its rules kept IN THE THEOREMS — MAX_DEPTH = 32 = 2⁵, MAX_STRING = 10⁶, arrays and object keys bounded to 10⁵, the three prototype-pollution poison keys (<strong>proto</strong>, constructor, prototype) dropped, and the nine Trojan-Source BIDI code points (five overrides U+202A..202E + four isolates U+2066..2069) stripped — process any input, sanitise any output by all standards, the rule sent by the theorems themselves so a code constant cannot drift from its sealed value</p></blockquote><p>These 7 facts hold by decision. Each was proven in Lean 4 — no Mathlib, checked sorry-free — and every sentence below links the proof that seals it. This note claims nothing beyond what its theorems settle: not that the domain is complete, only that the prose says nothing the proofs do not. It was written by reading the sealed ledger; read the proofs, not the prose.</p><h2 id="the-facts-each-backed-by-its-proof" tabindex="-1">The facts, each backed by its proof <a class="header-anchor" href="#the-facts-each-backed-by-its-proof" aria-label="Permalink to “The facts, each backed by its proof”">​</a></h2><ul><li>The sanitiser collapses nesting past MAX_DEPTH = 32 = 2⁵ — a bounded fold depth, no stack blow-up on a hostile input. — <a href="/theorem/sanitize_max_depth_is_two_pow_five">proof</a>.</li><li>A string is bounded to MAX_STRING = 1000000 = 10⁶ bytes — never unbounded output. — <a href="/theorem/sanitize_max_string_is_ten_pow_six">proof</a>.</li><li>Arrays and object keys are each bounded to 100000 = 10⁵ — a hostile &quot;allocate forever&quot; is refused equally for both. — <a href="/theorem/sanitize_array_and_keys_are_ten_pow_five">proof</a>.</li><li>Prototype-pollution defence: exactly three poison keys are dropped by all standards — <strong>proto</strong>, constructor, prototype (1 + 1 + 1 = 3). — <a href="/theorem/sanitize_poison_keys_are_three">proof</a>.</li><li>The Trojan-Source BIDI OVERRIDE block U+202A..U+202E is five code points (8238 − 8234 + 1 = 5) — all stripped. — <a href="/theorem/sanitize_bidi_overrides_are_five">proof</a>.</li><li>The BIDI ISOLATE block U+2066..U+2069 is four code points (8297 − 8294 + 1 = 4) — all stripped. — <a href="/theorem/sanitize_bidi_isolates_are_four">proof</a>.</li><li>Nine dangerous BIDI code points in total are stripped (5 overrides + 4 isolates = 9) — the full Trojan-Source surface (CVE-2021-42574). — <a href="/theorem/sanitize_bidi_points_are_nine">proof</a>.</li></ul><h2 id="provenance" tabindex="-1">Provenance <a class="header-anchor" href="#provenance" aria-label="Permalink to “Provenance”">​</a></h2><p>These 7 proofs fold, order-invariant, to the receipt <code>8ef3fc8e-06aa-8e56-8cec-411d4f1a6b98</code> — recompute it from the same ledger and it returns. The note itself content-addresses to a uuid, so any edit is visible. Writing descends from reading: this note holds only what the proofs it links already sealed, and it was audited by uuidna&#39;s own honesty gate before it was published — a sentence that overreached a proof would have been refused, not shipped.</p><p>Source · <a href="https://github.com/uuidna/uuidna/blob/main/lean/Sanitize.lean" target="_blank" rel="noreferrer">lean/Sanitize.lean</a> · <a href="/theorems">all theorems</a></p><hr><p><strong>Audited before published</strong> · this note passed uuidna&#39;s honesty gate at build time — every claim above links the proof that seals it. Content-address <code>dad0c39e</code> · proofs fold to receipt <code>8ef3fc8e</code> (the handles; the full uuids are in this page&#39;s meta, recomputable) · 7 sealed theorems.</p><p><a href="/publications">All publications</a> · <a href="/theorems">All theorems</a> · <a href="/trials">How auditing works</a></p>`,11)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};